/* Guide: practice questions.
 *
 * The figures on this page are generated by the same engine that runs the live
 * test, using demo ids that are NOT in the scored bank - so showing full worked
 * answers here gives nothing away about the real items.
 *
 * Carries Quiz structured data in Google's practice-problem shape for the two
 * item types whose answers are expressible as text. */
'use strict';

var guide = require('./_guide.js');
var P = require('../_parts.js');
var matrix = require('../../lib/matrix.js');
var series = require('../../lib/series.js');
var spatial = require('../../lib/spatial.js');
var render = require('../../lib/render.js');
var cfg = require('../../../site.config.js');

// ------------------------------------------------------------- demo items ---

var demoMatrix = matrix.build({
  id: 'DEMO.PRACTICE.MAT',
  family: 'attr',
  rules: {
    shape: { kind: 'fixed', value: 'hexagon' },
    size: { kind: 'progress', domain: ['sm', 'md', 'lg'], starts: [0, 1, 2], step: 1 },
    fill: { kind: 'latin', domain: ['none', 'light', 'solid'], shift: 1 }
  }
});

var demoLogic = matrix.build({ id: 'DEMO.PRACTICE.XOR', family: 'logic', op: 'xor' });

var demoSeries = series.build({
  id: 'DEMO.PRACTICE.NL',
  show: 5,
  gen: { kind: 'quad', a0: 3, d0: 4, dd: 3 }
});

var demoLetters = series.build({
  id: 'DEMO.PRACTICE.LT',
  show: 5,
  gen: { kind: 'lettersCycle', start: 'C', steps: [3, 1] }
});

var demoSpatial = spatial.build({
  id: 'DEMO.PRACTICE.SR',
  cells: [[1, 0], [2, 0], [0, 1], [1, 1], [1, 2]],
  turns: 1
});

var demoVerbal = {
  stem: 'Archipelago is to island as constellation is to ___',
  options: ['star', 'sky', 'telescope', 'galaxy', 'planet'],
  answerIndex: 0,
  rationale: 'The relation is collection to member. An archipelago is a group of islands, so a ' +
    'constellation is a group of stars. "Galaxy" is another kind of collection, but it is not what a ' +
    'constellation is made of.'
};

// ------------------------------------------------------------- presentation --

function figOptions(item, opts) {
  return '<div class="options opts-fig" style="margin-bottom:16px">' +
    item.options.map(function (v, i) {
      var right = opts.reveal && i === item.answer;
      return '<div class="opt" style="cursor:default' +
        (right ? ';border-color:var(--good);box-shadow:inset 0 0 0 1px var(--good)' : '') + '">' +
        '<span class="opt-key"' + (right ? ' style="background:var(--good);color:#fff;border-color:var(--good)"' : '') + '>' +
        String.fromCharCode(65 + i) + '</span>' +
        render.option(item, v) + '</div>';
    }).join('') + '</div>';
}

function textOptions(values, answerIndex, cls) {
  return '<div class="options ' + cls + '" style="margin-bottom:16px">' +
    values.map(function (v, i) {
      var right = i === answerIndex;
      return '<div class="opt" style="cursor:default' +
        (right ? ';border-color:var(--good);box-shadow:inset 0 0 0 1px var(--good)' : '') + '">' +
        '<span class="opt-key"' + (right ? ' style="background:var(--good);color:#fff;border-color:var(--good)"' : '') + '>' +
        String.fromCharCode(65 + i) + '</span>' +
        (cls === 'opts-term'
          ? '<span class="cs-opt-term">' + P.esc(v) + '</span>'
          : '<span class="cs-opt-text">' + P.esc(v) + '</span>') +
        '</div>';
    }).join('') + '</div>';
}

function example(n, heading, promptHtml, stimHtml, optionsHtml, answerLabel, explanation) {
  return '<div class="card" style="margin:1.6em 0">' +
    '<h3 style="margin-top:0">Example ' + n + ': ' + P.esc(heading) + '</h3>' +
    (promptHtml ? '<p class="q-prompt">' + promptHtml + '</p>' : '') +
    (stimHtml ? '<div class="stim-wrap">' + stimHtml + '</div>' : '') +
    optionsHtml +
    '<details class="review-item" style="margin:0">' +
      '<summary><b>Show the answer</b></summary>' +
      '<div class="review-body">' +
        '<p><b>Answer: ' + P.esc(answerLabel) + '</b></p>' +
        '<p style="margin:0">' + explanation + '</p>' +
      '</div>' +
    '</details>' +
    '</div>';
}

// ------------------------------------------------------- structured data ----

function qNode(name, text, options, answerIndex, explanation) {
  return {
    '@type': 'Question',
    eduQuestionType: 'Multiple choice',
    learningResourceType: 'Practice problem',
    name: name,
    text: text,
    encodingFormat: 'text/html',
    suggestedAnswer: options.map(function (o, i) {
      return i === answerIndex ? null : {
        '@type': 'Answer', position: i, encodingFormat: 'text/html', text: String(o)
      };
    }).filter(Boolean),
    acceptedAnswer: {
      '@type': 'Answer',
      position: answerIndex,
      encodingFormat: 'text/html',
      text: String(options[answerIndex]),
      explanation: explanation
    }
  };
}

var quizJsonLd = {
  '@context': 'https://schema.org/',
  '@type': 'Quiz',
  name: 'IQ test practice questions',
  about: { '@type': 'Thing', name: 'Cognitive ability test practice' },
  educationalLevel: 'Adult',
  inLanguage: 'en',
  isAccessibleForFree: true,
  provider: { '@id': cfg.origin + '/#org' },
  hasPart: [
    qNode(
      'Number series practice question',
      'What comes next in the series ' + demoSeries.shown.join(', ') + ', ?',
      demoSeries.options, demoSeries.answer,
      'The differences are 4, 7, 10, 13 - each one 3 larger than the last. The next difference is 16.'
    ),
    qNode(
      'Letter series practice question',
      'What comes next in the series ' + demoLetters.shown.join(', ') + ', ?',
      demoLetters.options, demoLetters.answer,
      'The step through the alphabet alternates: forward 3, then forward 1.'
    ),
    qNode(
      'Verbal analogy practice question',
      demoVerbal.stem,
      demoVerbal.options, demoVerbal.answerIndex,
      demoVerbal.rationale
    )
  ]
};

module.exports = guide({
  slug: 'iq-test-practice-questions',
  crumb: 'Practice questions',
  h1: 'IQ test practice questions, with worked answers',
  title: 'IQ Test Practice Questions With Answers | CogniScale',
  description: 'Six worked IQ test practice questions - figural matrices, figure logic, number and letter series, spatial rotation and verbal analogies - with answers.',
  lede: 'One worked example of every question type used on this site, with the reasoning spelled out. None of these are among the 30 scored questions, so working through them will not distort your result.',
  updated: '2026-09-06',
  published: '2026-09-06',
  toc: [
    { id: 'matrices', label: 'Figural matrices' },
    { id: 'logic', label: 'Boolean figure logic' },
    { id: 'series', label: 'Number and letter series' },
    { id: 'spatial', label: 'Spatial rotation' },
    { id: 'verbal', label: 'Verbal analogies' },
    { id: 'strategy', label: 'General strategy' }
  ],
  head: render.defs(),

  bodyTop:
    '<div class="note">' +
      '<p style="margin:0"><b>A word about practice.</b> Practising a format reliably improves your score ' +
      '<em>on that format</em>, which is a practice effect rather than a change in ability. That is worth ' +
      'knowing in both directions: it means a bit of familiarity stops the format itself from being the ' +
      'obstacle, and it means a score obtained after heavy practice on the same test is inflated. ' +
      'Everything below is a demonstration of how each type works, not a coaching drill.</p>' +
    '</div>' +

    '<h2 id="matrices">Figural matrices</h2>' +
    '<p>A three-by-three grid of figures with the bottom-right cell missing. One or more rules govern how ' +
    'the figures change across each row; your job is to work out every rule and apply them all at once. ' +
    'Difficulty is driven mainly by <b>how many rules run simultaneously</b> - one is easy, three is hard.</p>' +

    example(1, 'two rules at once',
      'Which figure completes the matrix?',
      render.matrixStimulus(demoMatrix),
      figOptions(demoMatrix, { reveal: true }),
      String.fromCharCode(65 + demoMatrix.answer),
      'Two rules are running. <b>Size</b> steps up along each row - small, medium, large - wrapping back ' +
      'round at the end. <b>Shading</b> is arranged so that each of the three shadings appears exactly ' +
      'once in every row and every column. The missing cell has to satisfy both at the same time. ' +
      'A useful habit: work out one attribute at a time and eliminate options as you go, rather than ' +
      'trying to hold the whole figure in mind at once.') +

    '<h2 id="logic">Boolean figure logic</h2>' +
    '<p>A variant where each cell is a grid of marks, and the third cell in a row is produced by combining ' +
    'the first two. The combination is one of: keep marks in either cell (union), keep only marks in both ' +
    '(intersection), keep marks in exactly one (exclusive-or), or start from the first and remove anything ' +
    'in the second (subtraction).</p>' +
    '<p>The trick is to check the <em>top two rows</em> first to identify which operation is in play, then ' +
    'apply it to the third. Test the operations in order and stop when one explains both complete rows.</p>' +

    example(2, 'find the operation, then apply it',
      'In each row, the third figure is derived from the first two. Which figure completes the bottom row?',
      render.matrixStimulus(demoLogic),
      figOptions(demoLogic, { reveal: true }),
      String.fromCharCode(65 + demoLogic.answer),
      'This one is <b>exclusive-or</b>: the third cell keeps only the marks that appear in exactly one of ' +
      'the first two cells. Marks present in <em>both</em> cancel out and disappear. If you assumed union ' +
      '(keep everything from both), you would end up with too many marks - and one of the distractors is ' +
      'exactly that answer, which is how these items catch a half-formed rule.'),

  bodyBottom:
    '<h2 id="series">Number and letter series</h2>' +
    '<p>A sequence follows a generating rule; you supply the next term. With numbers, the reliable opening ' +
    'move is to <b>write down the differences between consecutive terms</b>. If the differences are ' +
    'constant, it is a simple arithmetic series. If the differences themselves form a pattern, you have a ' +
    'second-order rule. If neither, check for multiplication, a recurrence (each term built from the two ' +
    'before it), or two sequences interleaved.</p>' +

    example(3, 'differences of differences',
      'What comes next in the series?',
      render.seriesStimulus(demoSeries),
      textOptions(demoSeries.options, demoSeries.answer, 'opts-term'),
      String(demoSeries.correct),
      'The differences are 4, 7, 10, 13 - and those rise by a constant 3 each time. So the next difference ' +
      'is 16, giving ' + demoSeries.shown[demoSeries.shown.length - 1] + ' + 16 = <b>' + demoSeries.correct + '</b>. ' +
      'Whenever a series grows faster than linearly but not by a constant multiplier, take differences twice.') +

    example(4, 'an alternating step through the alphabet',
      'What comes next in the series?',
      render.seriesStimulus(demoLetters),
      textOptions(demoLetters.options, demoLetters.answer, 'opts-term'),
      String(demoLetters.correct),
      'Convert letters to positions first - that turns the problem back into a number series. ' +
      'C=3, F=6, G=7, J=10, K=11. The steps are +3, +1, +3, +1, so the next step is +3, giving position ' +
      '14: <b>' + demoLetters.correct + '</b>. Letter series are almost always number series in disguise.') +

    '<h2 id="spatial">Spatial rotation</h2>' +
    '<p>You are shown a figure and must pick the option that is the same figure <b>rotated</b> - not ' +
    'reflected. The distractors are mirror images, and they are genuinely hard, because a reflection has ' +
    'the same outline, the same number of cells and the same overall shape. It is only the handedness that ' +
    'differs.</p>' +
    '<p>The technique that works: pick one distinctive feature - a protruding arm, a corner notch - and ' +
    'track where it must end up relative to the rest of the figure after the turn. If an option has that ' +
    'feature on the wrong side, it is a reflection, and no amount of rotation will fix it.</p>' +

    example(5, 'rotation versus reflection',
      'Which figure is a rotation of the figure on the left?',
      '<div class="spatial-stim">' + render.spatialStimulus(demoSpatial) +
        '<span class="arrow" aria-hidden="true">&rarr;</span>' +
        '<span class="muted small">rotate this</span></div>',
      figOptions(demoSpatial, { reveal: true }),
      String.fromCharCode(65 + demoSpatial.answer),
      'This figure is <b>chiral</b>: its mirror image cannot be produced by any rotation, however far you ' +
      'turn it. Every wrong option here is that mirror image at some angle, or a figure with one cell ' +
      'moved. Turning the page - or your head - is a legitimate strategy and genuinely helps.') +

    '<h2 id="verbal">Verbal analogies</h2>' +
    '<p>Two words stand in some relation; you must complete a second pair standing in the same relation. ' +
    'The discipline that makes these tractable is to <b>name the relation explicitly before looking at the ' +
    'options</b>. Vague feelings of association lead straight to the distractors, which are chosen to be ' +
    'associated with the right answer without standing in the right relation to it.</p>' +

    example(6, 'name the relation first',
      P.esc(demoVerbal.stem),
      '',
      textOptions(demoVerbal.options, demoVerbal.answerIndex, 'opts-text'),
      demoVerbal.options[demoVerbal.answerIndex],
      P.esc(demoVerbal.rationale) + ' Naming the relation - "a collection and the thing it is made of" - ' +
      'settles it before the options can mislead you. "Sky" and "telescope" are merely associated with ' +
      'constellations; association is not the relation being tested.') +

    '<h2 id="strategy">General strategy</h2>' +
    '<ol>' +
      '<li><b>Answer everything.</b> On this test and most others, unanswered items count as wrong and ' +
      'there is no penalty for guessing. Even a blind guess on a five-option item is worth 20%.</li>' +
      '<li><b>Eliminate before you choose.</b> Distractors are built to be wrong in one specific way. ' +
      'Finding that way is usually faster than verifying the right answer from scratch.</li>' +
      '<li><b>Do not stall.</b> A hard item costing five minutes can cost you three easy items at the end. ' +
      'Mark your best guess, move on, come back if time allows.</li>' +
      '<li><b>State the rule in words.</b> On matrices and series, saying the rule aloud - "shading moves ' +
      'one place right each row" - catches errors that silent pattern-matching does not.</li>' +
      '<li><b>Take differences.</b> For any number series, this is the first move, every time.</li>' +
      '<li><b>Sit somewhere quiet.</b> Interruptions cost more than most people expect on timed reasoning ' +
      'tasks, and the test conditions are part of what the score assumes.</li>' +
    '</ol>',

  faq: [
    {
      q: 'Do these practice questions appear on the real test?',
      a: '<p>No. They are generated by the same engine but with ids that are not in the scored bank, ' +
         'specifically so that full worked answers can be published here without compromising the test.</p>'
    },
    {
      q: 'Does practising improve your IQ score?',
      a: '<p>It improves your score on the practised format, which is a practice effect rather than a ' +
         'change in underlying ability. Familiarity with the format does help by stopping the format ' +
         'itself from being an obstacle, but repeated practice on the same items produces an inflated ' +
         'score that means less, not more.</p>'
    },
    {
      q: 'What is the hardest type of IQ question?',
      a: '<p>It varies by person, which is the point of reporting a domain profile. Statistically, ' +
         'three-dimensional rotation items tend to have the lowest proportion correct of the common ' +
         'formats, and multi-rule figural matrices become very demanding once three rules run at once.</p>'
    }
  ],

  related: [
    { href: '/test/', title: 'Take the full test', text: 'Thirty scored questions with an instant, error-bounded result.' },
    { href: '/methodology/', title: 'How the questions are built', text: 'The rule taxonomy behind each item type, and how they are verified.' },
    { href: '/guides/fluid-vs-crystallised-intelligence/', title: 'Fluid vs crystallised intelligence', text: 'Which ability each question type actually taps.' },
    { href: '/guides/iq-score-ranges/', title: 'IQ score ranges', text: 'What your eventual score corresponds to.' }
  ]
});

module.exports.jsonld.push(quizJsonLd);
